(()=>{const featureList=['Instant activation','Up to +22,000 channels','Up to +88,000 VODs, Series','0.1 Credit = 1 Month','0.3 Credit = 3 Months','0.5 Credit = 6 Months','1 Credit = 12 Months','24/7 support','Full API access','Own domain / white-label support'];function fixButtons(){document.querySelectorAll('a.btn,a[data-wa]').forEach(a=>{const text=a.textContent.trim().toLowerCase(),card=a.closest('.card'),heading=card?.querySelector('h3')?.textContent||'';if(text==='whatsapp'||text.includes('contact')||text.includes('support'))a.href='/contact/';else if(text.includes('reseller')||heading.includes('Credit')||heading.includes('Grow'))a.href='/reseller/';else if(text.includes('setup')||text.includes('app'))a.href='/guides/';else a.href='/pricing/';a.target='';a.removeAttribute('rel')})}function resellerCards(){if(location.pathname!=='/reseller/')return;document.querySelectorAll('.section-head').forEach(head=>{if(head.textContent.includes('Reseller credit packages')){const h2=head.querySelector('h2');if(h2)h2.textContent='Tivione IPTV Reseller Packages';let p=head.querySelector('p');if(!p){p=document.createElement('p');p.className='muted';head.append(p)}p.textContent='Launch, manage and scale your IPTV business with flexible credits, dedicated support and professional tools.'}});document.querySelectorAll('.card').forEach(card=>{const title=card.querySelector('h3')?.textContent||'';if((title.includes('Credit')||title.includes('Grow'))&&!card.querySelector('.reseller-server-features')){const d=document.createElement('details');d.className='reseller-server-features';d.innerHTML='<summary>Server features included</summary><ul>'+featureList.map(f=>'<li>'+f+'</li>').join('')+'</ul>';card.append(d)}})}function home(){if(location.pathname!=='/'||document.querySelector('.home-proof'))return;const hero=document.querySelector('.hero');if(!hero)return;const s=document.createElement('section');s.className='home-proof';s.innerHTML='<div class="wrap proof-grid"><div class="proof-item"><strong>Global delivery</strong><span>Optimized routes for compatible devices.</span></div><div class="proof-item"><strong>Clear setup paths</strong><span>Choose a plan, select a player, then follow the guide.</span></div><div class="proof-item"><strong>Support when needed</strong><span>Use the contact page for plan and setup help.</span></div></div>';hero.after(s)}function run(){fixButtons();resellerCards();home()}setTimeout(run,450);document.addEventListener('DOMContentLoaded',run)})();
